const gruposSinonimos = { mascotas: ['gato', 'perro', 'mascota', 'animal', 'felino', 'canino'] };
const normalize=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const roots=s=>[...new Set((normalize(s).match(/[a-z0-9]+/g)||[]).filter(w=>w.length>=4).map(w=>w.slice(0,5)))];
const query=$('[A1] Entrada RAG').first().json.query;
const consulta=typeof query==='string'?query:JSON.stringify(query||'');
const palabras=(normalize(consulta).match(/[a-z0-9]+/g)||[]);
const sinonimos=[];
for(const grupo of Object.values(gruposSinonimos)){
 const terminos=grupo.map(normalize);
 if(terminos.some(t=>palabras.some(p=>p===t||p===t+'s'||p===t+'es')))sinonimos.push(...terminos);
}
const q=roots(consulta+' '+sinonimos.join(' '));
const x=$input.first().json;
if(!Array.isArray(x.results))throw new Error('Respuesta RAG sin results');
const nombres={'dfl-yy0nd3gni48nkodn8r1xevrnljm3':'Reglamento_Interno_Edificio.md','dfl-ze97pjmxpsyz2i0v1gfid0die0ma':'Normativa_Consorcios_CABA_Resumen.md'};
const sections=[];
for(const r of x.results){
 if(typeof r.score!=='number'||r.score<0.005||typeof r.content!=='string')continue;
 const filename=nombres[r.static_fields?.parsed_directory_file_id]||r.metadata?.file_name||'Fuente no identificada';
 const parts=r.content.split(/(?=^#{2,3}\s+)/gm).filter(s=>s.trim());
 for(const part of parts){
  const title=(part.match(/^#{2,3}\s+(.+)$/m)||[])[1]||'Inicio del documento';
  const words=new Set(roots(part));const matches=q.filter(w=>words.has(w)).length;
  sections.push({texto:part.trim().slice(0,1200),fuente:filename+' · '+title.trim(),score:r.score,matches});
 }
}
sections.sort((a,b)=>b.matches-a.matches||b.score-a.score);
const seen=new Set(),best=[];
for(const s of sections){const key=normalize(s.fuente);if(seen.has(key))continue;seen.add(key);best.push({texto:s.texto,fuente:s.fuente,score:s.score});if(best.length===3)break;}
return [{json:{response:best.length?JSON.stringify(best):'SIN_FRAGMENTOS'}}];
